        private INodeData CreateNodeData(NodeType nodeType)
        {
            return nodeType switch
            {
                NodeType.Branch => new BranchData(),
                NodeType.Extension => new ExtensionData(),
                NodeType.Leaf => new LeafData(),
                _ => null,
            };
        }

        public override string ToString()
        {
#if DEBUG
            return
